'use client';

/**
 * @file layerScopedContext.tsx
 * @input Surface-scoped React contexts and layer content
 * @output Private context creation and whole-value content boundary
 * @position AST-038 surface membership; unrelated contexts retain their owners
 */

import {createContext, useState, type Context, type ReactNode} from 'react';
import {createSharedContext} from '../utils/sharedContext';
import {realmValue, sharedKey} from '../utils/sharedRealm';

type Reset = (children: ReactNode) => ReactNode;
/**
 * The reset of each layer-scoped context from every copy of Core on this
 * React. A layer boundary from any of those copies resets them all, and never
 * renders another React's contexts.
 */
const resetsByReact = realmValue(
  sharedKey('layer-scoped-context-resets', 2),
  () => new WeakMap<typeof createContext, Map<Context<unknown>, Reset>>(),
  value => value instanceof WeakMap,
);
let resets = resetsByReact.get(createContext);
if (resets == null) {
  resets = new Map();
  resetsByReact.set(createContext, resets);
}
const reactResets = resets;

/**
 * Create a surface-scoped context whose whole default applies in a new layer.
 * The name and version register it like `createSharedContext`.
 */
export function createLayerScopedContext<T>(
  name: string,
  version: number,
  defaultValue: T,
): Context<T> {
  const Context = createSharedContext(name, version, defaultValue);
  if (!reactResets.has(Context as Context<unknown>)) {
    reactResets.set(Context as Context<unknown>, children => (
      <Context value={defaultValue}>{children}</Context>
    ));
  }
  return Context;
}

export function LayerContentBoundary({
  children,
}: {
  children: ReactNode;
}): ReactNode {
  // Keep the provider chain stable for this mount: lazy imports must not
  // remount existing content and discard its state or focus.
  const [resetChain] = useState(() => [...reactResets.values()]);
  return resetChain.reduceRight(
    (content, reset): ReactNode => reset(content),
    children,
  );
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file numberInputCommit.ts
 * @input A NumberInput draft and the field's validation constraints
 * @output A single commit, clear, or revert decision for the whole draft
 * @position Shared internal draft validation and commit policy for NumberInput and its live consumers
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/NumberInput/NumberInput.tsx
 * - /packages/core/src/NumberInput/numberInputCommit.test.ts
 * - /packages/core/src/Table/plugins/filtering/useTableFiltering.tsx
 * - /packages/core/src/PowerSearch/PowerSearchValueEditor.tsx
 */

import type {Locale} from '@astryxdesign/core/i18n';
import {parseLocaleNumber} from './numberParser';

interface NumberInputValidationOptions {
  min?: number | null;
  max?: number | null;
  isIntegerOnly?: boolean;
  locale?: Locale;
}

export type NumberInputCommitDecision =
  | {type: 'commit'; value: number; didClamp: boolean}
  | {type: 'clear'}
  | {type: 'revert'};

function parseNumericInput(
  input: string,
  options: Pick<NumberInputValidationOptions, 'isIntegerOnly' | 'locale'>,
): number | null {
  const trimmed = input.trim();
  if (trimmed === '') {
    return null;
  }

  const value = parseLocaleNumber(trimmed, options.locale);
  if (value == null || !Number.isFinite(value)) {
    return null;
  }
  if (options.isIntegerOnly && !Number.isInteger(value)) {
    return null;
  }
  return value;
}

export function parseNumberInput(
  input: string,
  options: NumberInputValidationOptions,
): number | null {
  const value = parseNumericInput(input, options);
  if (value === null) {
    return null;
  }
  if (options.min != null && value < options.min) {
    return null;
  }
  if (options.max != null && value > options.max) {
    return null;
  }
  return value;
}

export function resolveNumberInputCommit(
  input: string,
  options: NumberInputValidationOptions & {hasClear: boolean},
): NumberInputCommitDecision {
  if (input.trim() === '') {
    return options.hasClear ? {type: 'clear'} : {type: 'revert'};
  }

  const value = parseNumericInput(input, options);
  if (value === null) {
    return {type: 'revert'};
  }

  const min =
    options.min == null
      ? null
      : options.isIntegerOnly
        ? Math.ceil(options.min)
        : options.min;
  const max =
    options.max == null
      ? null
      : options.isIntegerOnly
        ? Math.floor(options.max)
        : options.max;
  if (min != null && max != null && min > max) {
    return {type: 'revert'};
  }

  const committedValue =
    min != null && value < min ? min : max != null && value > max ? max : value;
  return {
    type: 'commit',
    value: committedValue,
    didClamp: committedValue !== value,
  };
}

