    // The width this divider draws, for its stand-in during a glide.
    '--_table-row-divider-width': {
      default: `var(--_table-panel-divider-width, ${borderVars['--border-width']})`,
      [stylex.when.ancestor(':last-child', tableRowMarker)]: '0px',
