  const segments = useMemo<ListWindowSegment[]>(() => {
    if (!isWindowed) {
      return data.length === 0
        ? []
        : [{type: 'rows', start: 0, end: data.length}];
    }
    return createListWindowSegments(
      data.length,
      rowHeight,
      start,
      end,
      focusIndex,
    );
