  const onRowFocus = useCallback(
    (key: string | number, focusTarget?: HTMLElement) => {
      focusNoteRef.current =
        noteFocusWithin(focusTarget ?? body.current) ?? focusNoteRef.current;
      setFocusedKey(key);
    },
    [body],
  );
